final class DeviceDomainUnitTest extends TestCase
{
    // --- DeviceAuthorizationGrantType ---

    public function test_grant_type_constant(): void
    {
        $this->assertSame('urn:ietf:params:oauth:grant-type:device_code', DeviceAuthorizationGrantType::DEVICE_CODE);
    }

    // --- DeviceAuthorizationStatus ---

    public function test_status_constants(): void
    {
        $this->assertSame('pending', DeviceAuthorizationStatus::PENDING);
        $this->assertSame('approved', DeviceAuthorizationStatus::APPROVED);
        $this->assertSame('denied', DeviceAuthorizationStatus::DENIED);
    }

    // --- DeviceAuthorization ---

    public function test_device_authorization_stores_fields(): void
    {
        $now = new DateTimeImmutable('2026-01-01T10:00:00+00:00');
        $expires = new DateTimeImmutable('2026-01-01T10:10:00+00:00');
        $auth = new AuthenticationResult(valid: true, id: 'u1', tenant: 't1');

        $da = new DeviceAuthorization(
            deviceCode: 'dc-123',
            userCode: 'ABCD-EFGH',
            tenant: 'tenant',
            clientId: 'client',
            scope: 'openid',
            audiences: ['aud1'],
            interval: 5,
            requestedAt: $now,
            expiresAt: $expires,
            status: DeviceAuthorizationStatus::PENDING,
            auth: $auth,
            lastPollAt: null
        );

        $this->assertSame('dc-123', $da->deviceCode);
        $this->assertSame('ABCD-EFGH', $da->userCode);
        $this->assertSame('tenant', $da->tenant);
        $this->assertSame('client', $da->clientId);
        $this->assertSame('openid', $da->scope);
        $this->assertSame(['aud1'], $da->audiences);
        $this->assertSame(5, $da->interval);
        $this->assertSame(DeviceAuthorizationStatus::PENDING, $da->status);
        $this->assertSame($auth, $da->auth);
        $this->assertNull($da->lastPollAt);
    }

    public function test_device_authorization_is_expired_when_past(): void
    {
        $expires = new DateTimeImmutable('2026-01-01T10:00:00+00:00');
        $da = $this->makeDeviceAuthorization(expiresAt: $expires);

        $after = new DateTimeImmutable('2026-01-01T10:01:00+00:00');
        $this->assertTrue($da->isExpired($after));
    }

    public function test_device_authorization_not_expired_when_before(): void
    {
        $expires = new DateTimeImmutable('2026-01-01T10:10:00+00:00');
        $da = $this->makeDeviceAuthorization(expiresAt: $expires);

        $before = new DateTimeImmutable('2026-01-01T10:00:00+00:00');
        $this->assertFalse($da->isExpired($before));
    }

    public function test_expires_in_returns_positive_seconds(): void
    {
        $now = new DateTimeImmutable('2026-01-01T10:00:00+00:00');
        $expires = new DateTimeImmutable('2026-01-01T10:01:00+00:00');
        $da = $this->makeDeviceAuthorization(expiresAt: $expires);

        $this->assertSame(60, $da->expiresIn($now));
    }

    public function test_expires_in_returns_zero_when_expired(): void
    {
        $expires = new DateTimeImmutable('2026-01-01T10:00:00+00:00');
        $da = $this->makeDeviceAuthorization(expiresAt: $expires);

        $after = new DateTimeImmutable('2026-01-01T10:05:00+00:00');
        $this->assertSame(0, $da->expiresIn($after));
    }

