    public function test_exception_authorization_pending(): void
    {
        $ex = DeviceAuthorizationException::authorizationPending();
        $this->assertSame('authorization_pending', $ex->error());
        $this->assertSame(400, $ex->statusCode());
    }

    public function test_exception_slow_down(): void
    {
        $ex = DeviceAuthorizationException::slowDown();
        $this->assertSame('slow_down', $ex->error());
    }

    public function test_exception_access_denied(): void
    {
        $ex = DeviceAuthorizationException::accessDenied();
        $this->assertSame('access_denied', $ex->error());
    }

    public function test_exception_expired_token(): void
