    // --- DeviceAuthorizationService ---

    public function test_create_authorization_returns_authorization_with_correct_fields(): void
    {
        $created = null;
        $gateway = $this->makeGateway(onCreate: function (DeviceAuthorization $a) use (&$created) {
            $created = $a;
        });
        $client = new ClientData('my-client', [DeviceAuthorizationGrantType::DEVICE_CODE], false);
        $service = new DeviceAuthorizationService($gateway);

        $auth = $service->createAuthorization('tenant', $client, 'openid', ['aud1']);

        $this->assertSame('tenant', $auth->tenant);
        $this->assertSame('my-client', $auth->clientId);
        $this->assertSame('openid', $auth->scope);
        $this->assertSame(['aud1'], $auth->audiences);
        $this->assertSame(DeviceAuthorizationStatus::PENDING, $auth->status);
        $this->assertSame(DeviceAuthorizationService::DEFAULT_INTERVAL, $auth->interval);
        $this->assertNull($auth->auth);
        $this->assertNull($auth->lastPollAt);
        $this->assertSame($auth, $created);
    }

    public function test_create_authorization_user_code_format(): void
    {
        $gateway = $this->makeGateway();
        $client = new ClientData('c', [], false);
        $service = new DeviceAuthorizationService($gateway);

        $auth = $service->createAuthorization('t', $client, '', []);

        $this->assertMatchesRegularExpression('/^[A-Z0-9]{4}-[A-Z0-9]{4}$/', $auth->userCode);
    }

