    public function test_approve_by_user_code_returns_false_when_not_pending(): void
    {
        $approved = $this->makeDeviceAuthorization(
            expiresAt: new DateTimeImmutable('2099-01-01T00:00:00+00:00'),
            status: DeviceAuthorizationStatus::APPROVED
        );
        $gateway = $this->makeGateway(byUserCode: $approved);
        $service = new DeviceAuthorizationService($gateway);
        $auth = new AuthenticationResult(valid: true, id: 'u1', tenant: 't');

