    public function test_approve_by_user_code_calls_gateway_approve(): void
    {
        $pending = $this->makeDeviceAuthorization(
            deviceCode: 'dc-xyz',
            expiresAt: new DateTimeImmutable('2099-01-01T00:00:00+00:00'),
            status: DeviceAuthorizationStatus::PENDING
        );
        $approvedCode = null;
        $gateway = $this->makeGateway(
            byUserCode: $pending,
            onApprove: function (string $code) use (&$approvedCode) {
                $approvedCode = $code;
                return true;
            }
        );
        $service = new DeviceAuthorizationService($gateway);
        $auth = new AuthenticationResult(valid: true, id: 'u1', tenant: 't');

        $result = $service->approveByUserCode('t', 'ABCD-EFGH', $auth);

        $this->assertTrue($result);
        $this->assertSame('dc-xyz', $approvedCode);
    }

