    public function test_generate_user_code_falls_back_to_uuid_when_all_attempts_collide(): void
    {
        $collision = $this->makeDeviceAuthorization();
        $gateway = $this->makeGateway(byUserCode: $collision);
        $client = new ClientData('c', [], false);
        $service = new DeviceAuthorizationService($gateway);

        $result = $service->createAuthorization('tenant', $client, 'openid', []);

        $this->assertMatchesRegularExpression(
            '/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/',
            $result->userCode
        );
    }

    public function test_grant_type_static_method(): void
    {
        $this->assertSame(DeviceAuthorizationGrantType::DEVICE_CODE, DeviceAuthorizationService::grantType());
    }

    // --- helpers ---

    private function makeDeviceAuthorization(
        string $deviceCode = 'dc-1',
        ?DateTimeImmutable $expiresAt = null,
        string $status = DeviceAuthorizationStatus::PENDING,
        ?AuthenticationResult $authResult = null,
        ?DateTimeImmutable $lastPollAt = null
    ): DeviceAuthorization {
        $expiresAt ??= new DateTimeImmutable('2099-01-01T00:00:00+00:00');
        return new DeviceAuthorization(
            deviceCode: $deviceCode,
            userCode: 'ABCD-EFGH',
            tenant: 'tenant',
            clientId: 'client',
            scope: 'openid',
            audiences: [],
            interval: 5,
            requestedAt: new DateTimeImmutable('2026-01-01T10:00:00+00:00'),
            expiresAt: $expiresAt,
            status: $status,
            auth: $authResult,
            lastPollAt: $lastPollAt
        );
    }

    private function makeGateway(
        ?DeviceAuthorization $byDeviceCode = null,
        ?DeviceAuthorization $byUserCode = null,
        ?callable $onCreate = null,
        ?callable $onApprove = null
    ): DeviceAuthorizationGateway {
        return new class ($byDeviceCode, $byUserCode, $onCreate, $onApprove) implements DeviceAuthorizationGateway {
            public function __construct(
                private ?DeviceAuthorization $byDeviceCode,
                private ?DeviceAuthorization $byUserCode,
                private $onCreate,
                private $onApprove
            ) {
            }
            public function create(DeviceAuthorization $a): void
            {
                if ($this->onCreate) {
                    ($this->onCreate)($a);
                }
            }
            public function findByDeviceCode(string $c): ?DeviceAuthorization
            {
                return $this->byDeviceCode;
            }
            public function findByUserCode(string $t, string $c): ?DeviceAuthorization
            {
                return $this->byUserCode;
            }
            public function approve(string $c, AuthenticationResult $a): bool
            {
                if ($this->onApprove) {
                    return ($this->onApprove)($c, $a);
                }
                return true;
            }
            public function deny(string $c): bool
            {
                return true;
            }
            public function touchPoll(string $c, DateTimeImmutable $n): void
            {
            }
            public function consume(string $c): void
            {
            }
        };
    }
}
